namespace NCode.Identity.OpenId.Core.Tests.ClientCertificates;

// Written by OpenSSL 3.2.4 with RSA 2048 keys and SHA-256 signatures: an issuer (CN=Interop CA), a client certificate
// (CN=Interop Leaf, serial 0x1234) that the issuer revoked for keyCompromise, and a delegated responder
// (CN=Interop Responder) with id-kp-OCSPSigning and id-pkix-ocsp-nocheck. The request is
// `openssl ocsp -issuer ca.pem -cert leaf.pem -no_nonce -reqout req.der`; the responses are
// `openssl ocsp -index index.txt -CA ca.pem -reqin req.der -ndays 1` with `-rsigner ca.pem` (responder named by
// name) and with `-rsigner responder.pem -resp_key_id` (responder named by key hash), produced 2026-10-24T20:32:24Z.
internal static class OcspOpenSslFixtures
{
    public static DateTimeOffset ProducedAt { get; } = new(2026, 10, 24, 20, 32, 24, TimeSpan.Zero);

    public const string IssuerCertificate =
        "";

    public const string ClientCertificate =
        "";

    public const string ResponderCertificate =
        "";

    public const string Request =
        "MEMwQTA/MD0wOzAJBgUrDgMCGgUABBTQK3fY5cntqxMHpfUKu/i85iavFwQUXRXppoS+l36tKJEgzsqHN+22OS4CAhI0";

    public const string ResponseSignedByIssuer =
        "";

    public const string ResponseSignedByDelegatedResponder =
        "";
}
